self.KB_CONTENT["card:752525"]={"id":"card:752525","ty":"card","sourceId":"752525","title":"『指定科目生失效作業』的作業目的為何？","ver":"iGP","topic":"總帳帳別","keywords":["總帳帳別","科目","進行","透過"],"y":"explain","answer":"可透過此作業將特定總帳帳別的會計科目作整批生批或失效。（例如當啟用一個新的副帳帳別時，因為為避免使用者會用到該帳別尚未維護好的會計科目，則可執行此作業先將會計科目全部作失效處理，待會計科目維護好後，再將科目進行生效處理，以供使用者後續的使用）","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
