self.KB_CONTENT["card:752341"]={"id":"card:752341","ty":"card","sourceId":"752341","title":"『拋轉會計傳票作業』中的『輸入單身序號間隔 (IncByN)』為何？","ver":"iGP","topic":"單身","keywords":["單身","傳票","拋轉","序號"],"y":"other","answer":"* 預設每10筆單身序號為間隔。亦可修改，但不可空白。* 此欄位僅可輸入1~10之數值。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
