self.KB_CONTENT["card:755876"]={"id":"card:755876","ty":"card","sourceId":"755876","title":"『品號品名對照表』中的『分類方式 (C10)』為何？","ver":"iGP","topic":"品號","keywords":["品號","分類","商品","品名"],"y":"other","answer":"* 共用參數設定作業中所設定的商品分類方式一、商品分類方式二、商品分類方式三、商品分類方式四。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
