self.KB_CONTENT["card:792374"]={"id":"card:792374","ty":"card","sourceId":"792374","title":"『產品序號期初導入作業』中的『控制編碼原則、已用商品序號及已用生管序號』為何？","ver":"GP4以上","topic":"品號","keywords":["品號","產品","序號","商品"],"y":"other","answer":"* 預設為該品號於「品號基本資料」之設定。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
