self.KB_CONTENT["card:793319"]={"id":"card:793319","ty":"card","sourceId":"793319","title":"『信用狀資料建立作業』中的『訂單單別 (TG003)』為何？","ver":"GP4以上","topic":"客戶","keywords":["客戶","訂單","單別","單號"],"y":"other","answer":"* [F2]客戶訂單資料查詢，若擷取之訂單資料不存在國外訂單，則顯示訊息提醒，但可接受。但不可空白。* 資料有變動時則會清除單號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
