self.KB_CONTENT["field:847834"]={"id":"field:847834","ty":"field","sourceId":"847834","title":"已生產量","ver":"GP40.iGP 以上","topic":"","keywords":[],"job":"製造命令建立作業","code":"","answer":"若確認無任何入庫單據，可以針對該筆製令單執行『製令領料重計作業-MOCB01』並取消勾選【重計庫存現行年月入庫單據之製令工單】，執行完畢後查看『製造命令建立作業-MOCI02』的【已生產量】應已會回寫正確","file":"fields.jsonl"};
